"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls";
import { plane } from "./three/Plane";
import { buildingMaterial } from "./three/Materials";
import { createCamera } from "./three/Camera";

export default function ThreeScene({ settings }) {
  const ref = useRef(null);
  const [camera, setCamera] = useState(null);

  useEffect(() => {
    const container = ref.current;
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(container.clientWidth, container.clientHeight);
    container.appendChild(renderer.domElement);

    const cam = createCamera(container.clientWidth, container.clientHeight);
    setCamera(cam);

    const scene = new THREE.Scene();

    const boxgeometry = new THREE.BoxGeometry();
    const cube = new THREE.Mesh(boxgeometry, buildingMaterial);
    scene.add(cube);

    plane.rotation.x = -Math.PI / 2;
    plane.position.y = -0.5;
    scene.add(plane);

    const light = new THREE.DirectionalLight(0xffffff, 1);
    light.position.set(2, 2, 2);
    scene.add(light);

    const controls = new OrbitControls(cam, renderer.domElement);
    controls.enableRotate = false;
    controls.enablePan = true;
    controls.enableZoom = true;
    controls.panSpeed = 1;
    controls.zoomSpeed = 1;
    controls.screenSpacePanning = true;

    let frame;
    const loop = () => {
      cube.rotation.x += 0.01;
      controls.update();
      renderer.render(scene, cam);
      frame = requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      cam.aspect = container.clientWidth / container.clientHeight;
      cam.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("resize", handleResize);
      container.removeChild(renderer.domElement);
      renderer.dispose();
      boxgeometry.dispose();
      buildingMaterial.dispose();
      controls.dispose();
    };
  }, [settings]);

  return <div ref={ref} className="w-full h-full bg-blue" />;
}
